  // Let's inspect the structure of the results table
  const mainRows = [];
  document.querySelectorAll('tr').forEach(tr => {
    const serviceNameEl = tr.querySelector('td:nth-child(1)');
    const timeEl = tr.querySelector('td:nth-child(2)');
    const costEl = tr.querySelector('td:nth-child(3)');
    if (serviceNameEl && timeEl && costEl) {
      mainRows.push({
        service: serviceNameEl.innerText.trim().replace(/\s+/g, ' '),
